"""U6 static terrain -- baked MAP + CHUNKS expanded into full tile maps.

The base64 blobs at the bottom are verbatim copies of ULTIMA6/MAP (32256 B) and
ULTIMA6/CHUNKS (65536 B) -- immutable game data (U6 "The False Prophet", v4.5).
DO NOT hand-edit the blobs; they are correct as generated. The functions above
ARE editable.

Layout (faithful to seg_101C.c -- C_101C_0306 / getChunkIdxAt C_101C_0CF7):
  CHUNKS  = 1024 chunks x 64 B, each an 8x8 tile block, row-major. chunk_id c ->
            CHUNKS[c*64 : c*64+64]; tile (cx,cy) = chunk[cy*8 + cx].
  MAP     = per-superchunk chunk-index, 256 ids x 12-bit (x1.5 B = 0x180 / sc).
    surface (z=0): 60 superchunks, id = (x>>7) + ((y>>7)<<3), data at id*0x180.
                   ids 0..59 only (the bottom-right 4 of the 8x8 grid are absent;
                   those world cells stay 0). 16x16 chunks/sc -> 128x128 tiles.
    dungeons z=1..5: 32x32 chunk-index, 0x600 B at z*0x600 + 0x5a00 -> 256x256.
  12-bit unpack: linear = row*W + col; byte_off = linear + (linear>>1); word =
  LE16 @ byte_off; id = (word>>4) if (col is odd) else (word & 0xfff).
"""
import base64

SURFACE_W = SURFACE_H = 1024
DUNGEON_W = DUNGEON_H = 256
_SC_BYTES = 0x180        # bytes per surface superchunk index
_SURFACE_SCS = 60        # present surface superchunks (ids 0..59)
_DUNGEON_BASE = 0x5a00   # file offset where the dungeon section starts
_DUNGEON_LEN = 0x600     # bytes per dungeon level index (4 superchunks)


def _chunk_id(idx, linear, col_odd):
    """Unpack a 12-bit chunk id at `linear` from a packed superchunk index."""
    off = linear + (linear >> 1)
    word = idx[off] | (idx[off + 1] << 8)
    return (word >> 4) if col_odd else (word & 0xfff)


def _blit(out, ow, bx, by, chunk):
    """Copy an 8x8 chunk into row-major buffer `out` (width ow) at (bx,by)."""
    for ty in range(8):
        row = (by + ty) * ow + bx
        out[row:row + 8] = chunk[ty * 8:ty * 8 + 8]


def expand_surface():
    """Full 1024x1024 surface terrain as a row-major bytearray ([y*1024 + x]).
    Cells under the 4 absent superchunks stay 0."""
    out = bytearray(SURFACE_W * SURFACE_H)
    for sc_id in range(_SURFACE_SCS):
        ox = (sc_id & 7) * 128
        oy = (sc_id >> 3) * 128
        idx = _MAP[sc_id * _SC_BYTES: sc_id * _SC_BYTES + _SC_BYTES]
        for crow in range(16):
            for ccol in range(16):
                cid = _chunk_id(idx, crow * 16 + ccol, ccol & 1)
                _blit(out, SURFACE_W, ox + ccol * 8, oy + crow * 8,
                      _CHUNKS[cid * 64:cid * 64 + 64])
    return out


def expand_dungeon(z):
    """Dungeon level z (1..5) as a row-major 256x256 bytearray."""
    if not 1 <= z <= 5:
        raise ValueError("dungeon level z must be 1..5")
    base = z * _DUNGEON_LEN + _DUNGEON_BASE
    idx = _MAP[base:base + _DUNGEON_LEN]
    out = bytearray(DUNGEON_W * DUNGEON_H)
    for crow in range(32):
        for ccol in range(32):
            cid = _chunk_id(idx, crow * 32 + ccol, ccol & 1)
            _blit(out, DUNGEON_W, ccol * 8, crow * 8,
                  _CHUNKS[cid * 64:cid * 64 + 64])
    return out


def tile_at(x, y, z=0):
    """Single terrain tile id at world (x,y,z). z=0 surface, 1..5 dungeon.
    Returns 0 for the absent surface corner."""
    x &= 0x3ff
    y &= 0x3ff
    if z == 0:
        sc_id = (x >> 7) + ((y >> 7) << 3)
        if sc_id >= _SURFACE_SCS:
            return 0
        idx = _MAP[sc_id * _SC_BYTES: sc_id * _SC_BYTES + _SC_BYTES]
        ccol = (x >> 3) & 0xf
        linear = ((y >> 3) & 0xf) * 16 + ccol
    else:
        base = z * _DUNGEON_LEN + _DUNGEON_BASE
        idx = _MAP[base:base + _DUNGEON_LEN]
        ccol = (x >> 3) & 0x1f
        linear = ((y >> 3) & 0x1f) * 32 + ccol
    cid = _chunk_id(idx, linear, ccol & 1)
    return _CHUNKS[cid * 64 + (y & 7) * 8 + (x & 7)]


